public class MemoizingProxyTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    interface Call {
        Object run() throws Throwable;
    }

    static Object safe(Call call) {
        try {
            return call.run();
        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
    }

    static class CountingPrices implements PriceService {
        int calls = 0;

        public int priceOf(String sku) {
            calls++;
            return sku.length() * 10;
        }

        public int total(String sku, int qty) {
            calls++;
            return sku.length() * 10 * qty;
        }
    }

    public static void main(String[] args) {
        CountingPrices real = new CountingPrices();
        final PriceService p = MemoizingProxy.memoize(real);

        check("priceOf(A)", 10, safe(() -> p.priceOf("A")));
        check("one call reached the real service", 1, real.calls);
        check("priceOf(A) a second time", 10, safe(() -> p.priceOf("A")));
        check("the repeat was served from the cache", 1, real.calls);
        check("priceOf(BB) value and delegate count", "20/2",
                safe(() -> p.priceOf("BB")) + "/" + real.calls);
        check("total(A, 3) value and delegate count", "30/3",
                safe(() -> p.total("A", 3)) + "/" + real.calls);
        check("total(A, 3) again is cached", "30/3",
                safe(() -> p.total("A", 3)) + "/" + real.calls);
        check("total(A, 4) is a different key", "40/4",
                safe(() -> p.total("A", 4)) + "/" + real.calls);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

