import java.lang.reflect.Proxy;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

// Provided -- do not edit.
interface PriceService {

    int priceOf(String sku);

    int total(String sku, int qty);
}

public class MemoizingProxy {

    public static PriceService memoize(PriceService target) {
        Map<String, Object> cache = new HashMap<>();
        return (PriceService) Proxy.newProxyInstance(
                PriceService.class.getClassLoader(),
                new Class<?>[] { PriceService.class },
                (proxy, method, args) -> {
                    String key = method.getName() + Arrays.toString(args);
                    if (cache.containsKey(key)) {
                        return cache.get(key);
                    }
                    Object result = method.invoke(target, args);
                    cache.put(key, result);
                    return result;
                });
    }
}
